package dashboard

import (
	"context"
	"fmt"

	"encore.dev/beta/auth"
)

type Response struct {
	Message string `json:"message"`
}

//encore:api auth
func Get(ctx context.Context) (*Response, error) {
	uid := auth.UserID()
	data := auth.Data[*auth.CustomData]()

	return &Response{
		Message: fmt.Sprintf("Hello %s, you are an %s", uid, data.Role),
	}, nil
}

